<script setup lang="ts">defineProps<{modelValue:boolean;label?:string;disabled?:boolean}>();const emit=defineEmits<{ 'update:modelValue':[value:boolean] }>();</script><template><label class="vx-switch"><input type="checkbox" role="switch" :checked="modelValue" :disabled="disabled" @change="emit('update:modelValue',($event.target as HTMLInputElement).checked)"/><span class="vx-switch__track"/><span v-if="label">{{label}}</span></label></template>